import java.util.Scanner;

public class E {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String s = scanner.next();
        int[] positionsV = new int[n], positionsK = new int[n], positionsX = new int[n];
        int countV = 0, countK = 0, countX = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == 'V') {
                positionsV[countV++] = i;
            } else if (c == 'K') {
                positionsK[countK++] = i;
            } else {
                positionsX[countX++] = i;
            }
        }
        long[][][][] dp = new long[n + 1][n + 1][n + 1][2];
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= n; j++)
                for (int k = 0; k <= n; k++)
                    for (int d = 0; d < 2; d++)
                        dp[i][j][k][d] = Long.MAX_VALUE;
        dp[0][0][0][0] = 0;
        for (int vCount = 0; vCount <= countV; vCount++) {
            for (int kCount = 0; kCount <= countK; kCount++) {
                for (int xCount = 0; xCount <= countX; xCount++) {
                    for (int t = 0; t < 2; t++) {
                        long current = dp[vCount][kCount][xCount][t];
                        if (current == Long.MAX_VALUE) continue;
                        if (vCount < countV) {
                            int vv = positionsV[vCount];
                            int moves = countSmaller(positionsV, vCount, vv) + countSmaller(positionsK, kCount, vv) + countSmaller(positionsX, xCount, vv);
                            dp[vCount + 1][kCount][xCount][1] = Math.min(dp[vCount + 1][kCount][xCount][1], current + moves);
                        }
                        if (kCount < countK && t == 0) {
                            int kk = positionsK[kCount];
                            int moves = countSmaller(positionsV, vCount, kk) + countSmaller(positionsK, kCount, kk) + countSmaller(positionsX, xCount, kk);
                            dp[vCount][kCount + 1][xCount][0] = Math.min(dp[vCount][kCount + 1][xCount][0], current + moves);
                        }
                        if (xCount < countX) {
                            int xx = positionsX[xCount];
                            int moves = countSmaller(positionsV, vCount, xx) + countSmaller(positionsK, kCount, xx) + countSmaller(positionsX, xCount, xx);
                            dp[vCount][kCount][xCount + 1][0] = Math.min(dp[vCount][kCount][xCount + 1][0], current + moves);
                        }
                    }
                }
            }
        }
        long answer = Long.MAX_VALUE;
        for (int i = 0; i < 2; i++) {
            answer = Math.min(answer, dp[countV][countK][countX][i]);
        }
        System.out.println(answer);
        scanner.close();
    }

    private static int countSmaller(int[] arr, int startIdx, int val) {
        int count = 0;
        for (int i = startIdx; i < arr.length && arr[i] < val; i++) {
            count++;
        }
        return count;
    }
}
