    elif c == 'K':
        positionsK.append(i)
    else:
        positionsX.append(i)

countV = len(positionsV)
countK = len(positionsK)
countX = len(positionsX)

# Initialize 4D DP array with infinity
import math
dp = [[[[math.inf for _ in range(2)] for _ in range(countX + 1)] for _ in range(countK + 1)] for _ in range(countV + 1)]
dp[0][0][0][0] = 0

def countSmaller(arr, startIdx, val):
    count = 0
    for i in range(startIdx, len(arr)):
        if arr[i] < val:
            count += 1
    return count

